mapper.select:
SELECT
a.*
FROM visual_screen.vs_business_info a
where 1=1

    and a.business_id = #{params.business_id}


    AND a.business_name like concat(concat('%',#{params.business_name}),'%')


    and a.business_state = #{params.business_state}


    and a.dep = #{params.dep}

ORDER BY a.business_id asc
LIMIT #{params.rows,jdbcType=INTEGER} OFFSET #{params.page,jdbcType=INTEGER}

SELECT
COUNT(*)
FROM visual_screen.vs_business_info a
where 1=1

    and a.business_id = #{params.business_id}


    AND a.business_name like concat(concat('%',#{params.business_name}),'%')


    and a.business_state = #{params.business_state}


    and a.dep = #{params.dep}

SELECT
*
FROM visual_screen.vs_business_info a
where 1=1

    and a.business_name = #{params.business_name}


    and a.business_state = #{params.business_state}


    and a.business_id != #{params.business_id}
